// The Forge's own store (ADR 0011): SQLite via node:sqlite, one file under
// DATA_DIR, holding exactly the Forge domain: forged champions, the
// creation ledger, and generation jobs. Accounts stay where they are
// (server/accounts.ts, JSON): rows here reference their ids as plain
// integers across the store boundary. Ledger-first economy: balances are
// never stored, only derived, so a grant, a spend, and a refund are all
// the same append.

import { mkdirSync } from 'node:fs';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import type { ForgedChampionDef } from '../src/sim/forge/forged_def';
import { BASE_RATING } from './rating';
import type { SpendSample } from './spend';

const SCHEMA = `
create table if not exists forged_champions (
  id text primary key,
  account_id integer not null,
  def text not null,
  status text not null check (status in ('draft', 'finalized')),
  assets text,
  created_at integer not null,
  updated_at integer not null,
  listed integer not null default 1,
  shared integer not null default 1,
  taken_down integer not null default 0
);
create table if not exists credits (
  id integer primary key autoincrement,
  account_id integer not null,
  delta integer not null,
  reason text not null,
  ref text,
  at integer not null
);
create table if not exists generation_jobs (
  id integer primary key autoincrement,
  forged_id text not null references forged_champions(id),
  account_id integer not null,
  status text not null check (status in ('running', 'success', 'failed')),
  stage text not null,
  error text,
  kind text,
  created_at integer not null,
  updated_at integer not null
);
create table if not exists forge_ratings (
  account_id integer primary key,
  rating integer not null,
  games integer not null
);
create table if not exists likes (
  account_id integer not null,
  forged_id text not null,
  at integer not null,
  primary key (account_id, forged_id)
);
create table if not exists reports (
  account_id integer not null,
  forged_id text not null,
  reason text not null,
  at integer not null,
  primary key (account_id, forged_id)
);
create table if not exists warnings (
  id integer primary key autoincrement,
  account_id integer not null,
  forged_id text not null,
  reason text not null,
  at integer not null
);
create table if not exists quota_events (
  id integer primary key autoincrement,
  account_id integer not null,
  action text not null,
  at integer not null
);
create table if not exists spend_samples (
  id integer primary key autoincrement,
  account_id integer not null,
  action text not null,
  detail text not null,
  provider text not null,
  credits real,
  input_tokens integer,
  output_tokens integer,
  cache_read_tokens integer,
  cache_write_tokens integer,
  at integer not null
);
create table if not exists art_candidates (
  id integer primary key autoincrement,
  forged_id text not null,
  account_id integer not null,
  kind text not null,
  prompt text not null,
  path text not null,
  provenance text not null,
  chosen integer not null default 0,
  at integer not null
);
`;

export interface ForgedRow {
  id: string;
  accountId: number;
  def: ForgedChampionDef;
  status: 'draft' | 'finalized';
  createdAt: number;
  updatedAt: number;
  // Gallery visibility: on by default, the creator can remove and relist.
  listed: boolean;
  // "Others may play it": on by default (game definition of the gallery).
  shared: boolean;
  // Moderation takedown: hidden and unplayable everywhere until lifted.
  takenDown: boolean;
}

export interface CreditEntry {
  accountId: number;
  delta: number;
  // 'weekly_grant' | 'finalize' | 'refund' | ... : the ledger keeps the
  // string, policy lives with the callers.
  reason: string;
  ref?: string;
  at: number;
}

// One generated 2D candidate (splash art or a spell icon) on a draft: the
// file it was downloaded to (relative to the assets dir), the prompt that
// made it, and whether the creator picked it. History, not state: rows
// append per generation and are pruned oldest-first past the cap.
export interface ArtCandidateRow {
  id: number;
  forgedId: string;
  accountId: number;
  // 'splash' | 'icon_Q' | ... : the store keeps the string, policy lives
  // in server/art.ts.
  kind: string;
  prompt: string;
  path: string;
  provenance: unknown;
  chosen: boolean;
  at: number;
}

// What a generation job is for, because the boot sweep must know what to
// give back: only a 'build' debited a creation. Legacy rows (pre-split)
// carry null and are treated as builds.
export type JobKind = 'build' | 'animate' | 'weapon';

export interface GenerationJobRow {
  id: number;
  forgedId: string;
  accountId: number;
  status: 'running' | 'success' | 'failed';
  stage: string;
  error: string | null;
  kind: JobKind | null;
  // What this job took off the ledger; null on a row older than embers.
  embers: number | null;
  createdAt: number;
  updatedAt: number;
}

interface ForgedRawRow {
  id: string;
  account_id: number;
  def: string;
  status: 'draft' | 'finalized';
  created_at: number;
  updated_at: number;
  listed: number;
  shared: number;
  taken_down: number;
}

interface ArtRawRow {
  id: number;
  forged_id: string;
  account_id: number;
  kind: string;
  prompt: string;
  path: string;
  provenance: string;
  chosen: number;
  at: number;
}

function toArt(r: ArtRawRow): ArtCandidateRow {
  let provenance: unknown = null;
  try {
    provenance = JSON.parse(r.provenance);
  } catch {}
  return {
    id: r.id,
    forgedId: r.forged_id,
    accountId: r.account_id,
    kind: r.kind,
    prompt: r.prompt,
    path: r.path,
    provenance,
    chosen: r.chosen === 1,
    at: r.at,
  };
}

interface JobRawRow {
  id: number;
  forged_id: string;
  account_id: number;
  status: 'running' | 'success' | 'failed';
  stage: string;
  error: string | null;
  kind: JobKind | null;
  embers: number | null;
  created_at: number;
  updated_at: number;
}

function toForged(r: ForgedRawRow): ForgedRow {
  return {
    id: r.id,
    accountId: r.account_id,
    def: JSON.parse(r.def) as ForgedChampionDef,
    status: r.status,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
    listed: r.listed === 1,
    shared: r.shared === 1,
    takenDown: r.taken_down === 1,
  };
}

// Every column a ForgedRow is built from, shared by each select below so a
// new column cannot be forgotten in one of them.
const FORGED_COLS =
  'id, account_id, def, status, created_at, updated_at, listed, shared, taken_down';

function toJob(r: JobRawRow): GenerationJobRow {
  return {
    id: r.id,
    forgedId: r.forged_id,
    accountId: r.account_id,
    status: r.status,
    stage: r.stage,
    error: r.error,
    kind: r.kind ?? null,
    embers: r.embers ?? null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

// Every column a GenerationJobRow is built from, shared by each job select.
const JOB_COLS =
  'id, forged_id, account_id, status, stage, error, kind, embers, created_at, updated_at';

export class ForgeStore {
  private readonly db: DatabaseSync;

  // ':memory:' gives tests a real store with no disk.
  constructor(file: string) {
    if (file !== ':memory:') mkdirSync(path.dirname(file), { recursive: true });
    this.db = new DatabaseSync(file);
    this.db.exec('pragma journal_mode = wal');
    this.db.exec(SCHEMA);
    // A store created before the gallery gains its columns in place;
    // create-if-not-exists alone never alters an existing table.
    this.ensureColumn('forged_champions', 'listed', 'listed integer not null default 1');
    this.ensureColumn('forged_champions', 'shared', 'shared integer not null default 1');
    this.ensureColumn('forged_champions', 'taken_down', 'taken_down integer not null default 0');
    // The editor's conversations (kit, stats) travel with the draft.
    this.ensureColumn('forged_champions', 'chats', 'chats text');
    // The two-phase build gave jobs a kind (what the boot sweep may
    // refund); pre-split rows keep null and count as builds.
    this.ensureColumn('generation_jobs', 'kind', 'kind text');
    // What the job debited (ADR 0017): a refund gives back exactly this,
    // and a weighted price cannot be re-derived after the fact. Rows from
    // before the ember ledger keep null and are refunded by the old rule.
    this.ensureColumn('generation_jobs', 'embers', 'embers integer');
  }

  private ensureColumn(table: string, name: string, ddl: string): void {
    const cols = this.db.prepare(`pragma table_info(${table})`).all() as unknown as {
      name: string;
    }[];
    if (!cols.some((c) => c.name === name)) this.db.exec(`alter table ${table} add column ${ddl}`);
  }

  close(): void {
    this.db.close();
  }

  // -- forged champions ---------------------------------------------------

  // Upserts a forged champion row. Validation is the caller's duty (the
  // deterministic validator gates every def before it is worth storing).
  // The gallery switches are not part of a save: they default on insert
  // and only setForgedVisibility and setTakenDown ever move them.
  saveForged(row: Omit<ForgedRow, 'listed' | 'shared' | 'takenDown'>): void {
    this.db
      .prepare(
        `insert into forged_champions (id, account_id, def, status, created_at, updated_at)
         values (?, ?, ?, ?, ?, ?)
         on conflict (id) do update set
           def = excluded.def, status = excluded.status, updated_at = excluded.updated_at`,
      )
      .run(
        row.id,
        row.accountId,
        JSON.stringify(row.def),
        row.status,
        row.createdAt,
        row.updatedAt,
      );
  }

  getForged(id: string): ForgedRow | null {
    const r = this.db.prepare(`select ${FORGED_COLS} from forged_champions where id = ?`).get(id) as
      | ForgedRawRow
      | undefined;
    return r ? toForged(r) : null;
  }

  listForgedByAccount(accountId: number): ForgedRow[] {
    const rows = this.db
      .prepare(
        `select ${FORGED_COLS} from forged_champions where account_id = ? order by created_at`,
      )
      .all(accountId) as unknown as ForgedRawRow[];
    return rows.map(toForged);
  }

  // The gallery's raw material: every finalized champion that is not taken
  // down, with its like count. Listing policy (listed, shared, search,
  // sort) lives with the callers in server/gallery.ts.
  listFinalized(): (ForgedRow & { likes: number })[] {
    const rows = this.db
      .prepare(
        `select ${FORGED_COLS.split(', ')
          .map((c) => `f.${c}`)
          .join(', ')},
           (select count(*) from likes l where l.forged_id = f.id) as likes
         from forged_champions f
         where f.status = 'finalized' and f.taken_down = 0
         order by f.updated_at desc`,
      )
      .all() as unknown as (ForgedRawRow & { likes: number })[];
    return rows.map((r) => ({ ...toForged(r), likes: r.likes }));
  }

  // The creator's two switches: gallery listing and "others may play it".
  setForgedVisibility(id: string, fields: { listed?: boolean; shared?: boolean }): void {
    const row = this.getForged(id);
    if (!row) return;
    this.db
      .prepare('update forged_champions set listed = ?, shared = ? where id = ?')
      .run((fields.listed ?? row.listed) ? 1 : 0, (fields.shared ?? row.shared) ? 1 : 0, id);
  }

  setTakenDown(id: string, down: boolean): void {
    this.db
      .prepare('update forged_champions set taken_down = ? where id = ?')
      .run(down ? 1 : 0, id);
  }

  deleteForged(id: string): void {
    this.db.prepare('delete from forged_champions where id = ?').run(id);
  }

  // Success in one write: the champion is sealed with its assets and
  // provenance, exactly once.
  setForgedFinalized(id: string, assets: unknown, now: number): void {
    this.db
      .prepare(
        `update forged_champions set status = 'finalized', assets = ?, updated_at = ? where id = ?`,
      )
      .run(JSON.stringify(assets), now, id);
  }

  // The explicit seal and unseal (server/seal.ts owns the policy).
  setForgedStatus(id: string, status: 'draft' | 'finalized', now: number): void {
    this.db
      .prepare('update forged_champions set status = ?, updated_at = ? where id = ?')
      .run(status, now, id);
  }

  forgedAssets(id: string): unknown {
    const r = this.db.prepare('select assets from forged_champions where id = ?').get(id) as
      | { assets: string | null }
      | undefined;
    if (!r?.assets) return null;
    try {
      return JSON.parse(r.assets);
    } catch {
      return null;
    }
  }

  // The editor's saved conversations, JSON beside the def: editor state,
  // not champion data, so it never touches updated_at.
  forgedChats(id: string): unknown {
    const r = this.db.prepare('select chats from forged_champions where id = ?').get(id) as
      | { chats: string | null }
      | undefined;
    if (!r?.chats) return null;
    try {
      return JSON.parse(r.chats);
    } catch {
      return null;
    }
  }

  setForgedChats(id: string, chats: unknown): void {
    this.db
      .prepare('update forged_champions set chats = ? where id = ?')
      .run(JSON.stringify(chats), id);
  }

  // Rewrites the sealed assets blob in place (the workshop's display
  // tuning); the caller owns merging into what forgedAssets returned.
  updateForgedAssets(id: string, assets: unknown, now: number): void {
    this.db
      .prepare('update forged_champions set assets = ?, updated_at = ? where id = ?')
      .run(JSON.stringify(assets), now, id);
  }

  // -- art candidates (plan-forge phase 4) ---------------------------------

  addArtCandidate(c: Omit<ArtCandidateRow, 'id' | 'chosen'>): number {
    const res = this.db
      .prepare(
        `insert into art_candidates (forged_id, account_id, kind, prompt, path, provenance, at)
         values (?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(c.forgedId, c.accountId, c.kind, c.prompt, c.path, JSON.stringify(c.provenance), c.at);
    return Number(res.lastInsertRowid);
  }

  listArtCandidates(forgedId: string): ArtCandidateRow[] {
    const rows = this.db
      .prepare('select * from art_candidates where forged_id = ? order by at, id')
      .all(forgedId) as unknown as ArtRawRow[];
    return rows.map(toArt);
  }

  getArtCandidate(id: number): ArtCandidateRow | null {
    const r = this.db.prepare('select * from art_candidates where id = ?').get(id) as
      | ArtRawRow
      | undefined;
    return r ? toArt(r) : null;
  }

  // The creator's pick: at most one chosen candidate per (champion, kind).
  chooseArtCandidate(forgedId: string, kind: string, id: number): void {
    this.db
      .prepare('update art_candidates set chosen = 0 where forged_id = ? and kind = ?')
      .run(forgedId, kind);
    this.db.prepare('update art_candidates set chosen = 1 where id = ?').run(id);
  }

  chosenArt(forgedId: string, kind: string): ArtCandidateRow | null {
    const r = this.db
      .prepare('select * from art_candidates where forged_id = ? and kind = ? and chosen = 1')
      .get(forgedId, kind) as ArtRawRow | undefined;
    return r ? toArt(r) : null;
  }

  // Drops the oldest unchosen candidates past `keep` for one (champion,
  // kind) and returns their file paths so the caller can unlink them; the
  // chosen candidate is never pruned.
  pruneArtCandidates(forgedId: string, kind: string, keep: number): string[] {
    const rows = this.db
      .prepare(
        `select id, path from art_candidates
         where forged_id = ? and kind = ? and chosen = 0 order by at desc, id desc`,
      )
      .all(forgedId, kind) as unknown as { id: number; path: string }[];
    const stale = rows.slice(Math.max(0, keep));
    for (const row of stale) this.db.prepare('delete from art_candidates where id = ?').run(row.id);
    return stale.map((r) => r.path);
  }

  // Every candidate of one champion, gone (a deleted draft); returns the
  // file paths for the caller to unlink.
  deleteArtCandidates(forgedId: string): string[] {
    const rows = this.db
      .prepare('select path from art_candidates where forged_id = ?')
      .all(forgedId) as unknown as { path: string }[];
    this.db.prepare('delete from art_candidates where forged_id = ?').run(forgedId);
    return rows.map((r) => r.path);
  }

  // -- the creation ledger ------------------------------------------------

  addCreditEntry(entry: CreditEntry): void {
    this.db
      .prepare('insert into credits (account_id, delta, reason, ref, at) values (?, ?, ?, ?, ?)')
      .run(entry.accountId, entry.delta, entry.reason, entry.ref ?? null, entry.at);
  }

  creditBalance(accountId: number): number {
    const r = this.db
      .prepare('select coalesce(sum(delta), 0) as balance from credits where account_id = ?')
      .get(accountId) as { balance: number };
    return r.balance;
  }

  // When the account last received an entry with this reason; null when
  // never. What the weekly allocation refresh paces itself by.
  lastCreditEntryAt(accountId: number, reason: string): number | null {
    const r = this.db
      .prepare('select max(at) as at from credits where account_id = ? and reason = ?')
      .get(accountId, reason) as { at: number | null };
    return r.at;
  }

  // -- likes, reports, warnings (plan-forge phase 7) -----------------------

  // One like per account per champion; liking twice is a no-op, so is
  // unliking what was never liked.
  setLike(accountId: number, forgedId: string, on: boolean, at: number): void {
    if (on) {
      this.db
        .prepare(
          'insert into likes (account_id, forged_id, at) values (?, ?, ?) on conflict do nothing',
        )
        .run(accountId, forgedId, at);
    } else {
      this.db
        .prepare('delete from likes where account_id = ? and forged_id = ?')
        .run(accountId, forgedId);
    }
  }

  likeCount(forgedId: string): number {
    const r = this.db
      .prepare('select count(*) as n from likes where forged_id = ?')
      .get(forgedId) as { n: number };
    return r.n;
  }

  likedBy(accountId: number, forgedId: string): boolean {
    return (
      this.db
        .prepare('select 1 from likes where account_id = ? and forged_id = ?')
        .get(accountId, forgedId) !== undefined
    );
  }

  likedIds(accountId: number): Set<string> {
    const rows = this.db
      .prepare('select forged_id from likes where account_id = ?')
      .all(accountId) as unknown as { forged_id: string }[];
    return new Set(rows.map((r) => r.forged_id));
  }

  // One report per account per champion, first reason kept.
  addReport(accountId: number, forgedId: string, reason: string, at: number): void {
    this.db
      .prepare(
        `insert into reports (account_id, forged_id, reason, at) values (?, ?, ?, ?)
         on conflict do nothing`,
      )
      .run(accountId, forgedId, reason, at);
  }

  reportCount(forgedId: string): number {
    const r = this.db
      .prepare('select count(*) as n from reports where forged_id = ?')
      .get(forgedId) as { n: number };
    return r.n;
  }

  addWarning(accountId: number, forgedId: string, reason: string, at: number): void {
    this.db
      .prepare('insert into warnings (account_id, forged_id, reason, at) values (?, ?, ?, ?)')
      .run(accountId, forgedId, reason, at);
  }

  warningCount(accountId: number): number {
    const r = this.db
      .prepare('select count(*) as n from warnings where account_id = ?')
      .get(accountId) as { n: number };
    return r.n;
  }

  // -- daily quota events (plan-forge phase 8) -----------------------------
  // Append-only, like the credits ledger: usage is derived by counting a
  // window, never stored. Policy (limits, the window) lives in
  // server/quotas.ts.

  addQuotaEvent(accountId: number, action: string, at: number): void {
    this.db
      .prepare('insert into quota_events (account_id, action, at) values (?, ?, ?)')
      .run(accountId, action, at);
  }

  quotaCountSince(accountId: number, action: string, since: number): number {
    const r = this.db
      .prepare(
        'select count(*) as n from quota_events where account_id = ? and action = ? and at > ?',
      )
      .get(accountId, action, since) as { n: number };
    return r.n;
  }

  // The calibration log (server/spend.ts, ADR 0017): append-only, read by
  // nothing in the game, written by every act that costs money.
  addSpendSample(s: SpendSample): void {
    this.db
      .prepare(
        'insert into spend_samples (account_id, action, detail, provider, credits, ' +
          'input_tokens, output_tokens, cache_read_tokens, cache_write_tokens, at) ' +
          'values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      )
      .run(
        s.accountId,
        s.action,
        s.detail,
        s.provider,
        s.credits ?? null,
        s.inputTokens ?? null,
        s.outputTokens ?? null,
        s.cacheReadTokens ?? null,
        s.cacheWriteTokens ?? null,
        s.at,
      );
  }

  listSpendSamples(since = 0): SpendSample[] {
    const rows = this.db
      .prepare('select * from spend_samples where at > ? order by at')
      .all(since) as Record<string, number | string | null>[];
    return rows.map((r) => ({
      accountId: Number(r.account_id),
      action: String(r.action) as SpendSample['action'],
      detail: String(r.detail) as SpendSample['detail'],
      provider: String(r.provider) as SpendSample['provider'],
      at: Number(r.at),
      ...(r.credits === null ? {} : { credits: Number(r.credits) }),
      ...(r.input_tokens === null ? {} : { inputTokens: Number(r.input_tokens) }),
      ...(r.output_tokens === null ? {} : { outputTokens: Number(r.output_tokens) }),
      ...(r.cache_read_tokens === null ? {} : { cacheReadTokens: Number(r.cache_read_tokens) }),
      ...(r.cache_write_tokens === null ? {} : { cacheWriteTokens: Number(r.cache_write_tokens) }),
    }));
  }

  // The same count over every account: what the server as a whole spent on
  // an action this window, for the ceiling no per-account limit can give.
  quotaCountAllSince(action: string, since: number): number {
    const r = this.db
      .prepare('select count(*) as n from quota_events where action = ? and at > ?')
      .get(action, since) as { n: number };
    return r.n;
  }

  // Housekeeping: events older than the widest window will never be
  // counted again; dropping them keeps the table bounded.
  pruneQuotaEvents(before: number): number {
    const res = this.db.prepare('delete from quota_events where at <= ?').run(before);
    return Number(res.changes);
  }

  // -- the Forge queue's own rating (plan-forge phase 6) -------------------
  // Mirrors the account registry's Elo pair (rating, ratedGames) for the
  // Forge queue alone: same policy (server/rating.ts), separate ladder,
  // stored with the rest of the Forge domain (ADR 0011).

  forgeRating(accountId: number): { rating: number; games: number } {
    const r = this.db
      .prepare('select rating, games from forge_ratings where account_id = ?')
      .get(accountId) as { rating: number; games: number } | undefined;
    return r ?? { rating: BASE_RATING, games: 0 };
  }

  // Every account with a Forge-queue rating, for that way's ladder.
  listForgeRatings(): { accountId: number; rating: number; games: number }[] {
    const rows = this.db
      .prepare('select account_id, rating, games from forge_ratings')
      .all() as unknown as { account_id: number; rating: number; games: number }[];
    return rows.map((r) => ({ accountId: r.account_id, rating: r.rating, games: r.games }));
  }

  // One rated Forge-queue match landed; the delta is already signed.
  applyForgeRating(accountId: number, delta: number): void {
    const cur = this.forgeRating(accountId);
    this.db
      .prepare(
        `insert into forge_ratings (account_id, rating, games) values (?, ?, ?)
         on conflict (account_id) do update set rating = excluded.rating, games = excluded.games`,
      )
      .run(accountId, cur.rating + delta, cur.games + 1);
  }

  // A leaver penalty: rating drops without counting a game, exactly like
  // the classic ladder's penalize().
  penalizeForgeRating(accountId: number, amount: number): void {
    const cur = this.forgeRating(accountId);
    this.db
      .prepare(
        `insert into forge_ratings (account_id, rating, games) values (?, ?, ?)
         on conflict (account_id) do update set rating = excluded.rating`,
      )
      .run(accountId, cur.rating - amount, cur.games);
  }

  // -- generation jobs ----------------------------------------------------

  createGenerationJob(
    forgedId: string,
    accountId: number,
    now: number,
    kind: JobKind = 'build',
    embers = 0,
  ): number {
    const res = this.db
      .prepare(
        `insert into generation_jobs (forged_id, account_id, status, stage, kind, embers, created_at, updated_at)
         values (?, ?, 'running', 'queued', ?, ?, ?, ?)`,
      )
      .run(forgedId, accountId, kind, embers, now, now);
    return Number(res.lastInsertRowid);
  }

  updateGenerationJob(
    id: number,
    fields: { status?: 'running' | 'success' | 'failed'; stage?: string; error?: string },
    now: number,
  ): void {
    const existing = this.getGenerationJob(id);
    if (!existing) return;
    this.db
      .prepare(
        'update generation_jobs set status = ?, stage = ?, error = ?, updated_at = ? where id = ?',
      )
      .run(
        fields.status ?? existing.status,
        fields.stage ?? existing.stage,
        fields.error ?? existing.error,
        now,
        id,
      );
  }

  getGenerationJob(id: number): GenerationJobRow | null {
    const r = this.db.prepare(`select ${JOB_COLS} from generation_jobs where id = ?`).get(id) as
      | JobRawRow
      | undefined;
    return r ? toJob(r) : null;
  }

  // The live job for a champion, if any: what stops a double finalize.
  runningJobFor(forgedId: string): GenerationJobRow | null {
    const r = this.db
      .prepare(
        `select ${JOB_COLS} from generation_jobs where forged_id = ? and status = 'running' limit 1`,
      )
      .get(forgedId) as JobRawRow | undefined;
    return r ? toJob(r) : null;
  }

  // Jobs still marked running (only a crash leaves them): the boot sweep
  // fails and refunds them, because the in-process work died with the
  // process.
  staleRunningJobs(): GenerationJobRow[] {
    const rows = this.db
      .prepare(`select ${JOB_COLS} from generation_jobs where status = 'running'`)
      .all() as unknown as JobRawRow[];
    return rows.map(toJob);
  }
}
